// @FIGURE_CODE_BEGIN
var ORANGE = '#D9724C';
var PURPLE = '#8B6BB1';
var THRESH = '#3a6ea8';
var GUIDE = '#c9c9c9';

function sigf(z) { return 1 / (1 + Math.exp(-z)); }
function cl(v, a, b) { return v < a ? a : (v > b ? b : v); }

var sigData = [], slopeData = [];
for (var i = 0; i <= 320; i++) {
  var z = -5 + 10 * i / 320;
  var s = sigf(z);
  sigData.push({ x: z, y: s });
  slopeData.push({ x: z, y: s * (1 - s) });
}

var state = { threshold: 0.5, mode: 'sigmoid', pinZ: null, showThreshold: false };
var hoverZ = null, dragging = false, movedWhileDown = false;
var chart = null;

function zStar() { var t = state.threshold; return Math.log(t / (1 - t)); }
function markerZ() { return hoverZ !== null ? hoverZ : state.pinZ; }

/* ---------- drawing helpers ---------- */
function haloText(ctx, txt, x, y, font, color, align, baseline, halo) {
  ctx.save();
  ctx.font = font;
  ctx.textAlign = align || 'left';
  ctx.textBaseline = baseline || 'alphabetic';
  if (halo !== 0) {
    ctx.lineWidth = halo || 3;
    ctx.strokeStyle = '#fff';
    ctx.lineJoin = 'round';
    ctx.strokeText(txt, x, y);
  }
  ctx.fillStyle = color;
  ctx.fillText(txt, x, y);
  ctx.restore();
}

function dline(ctx, x1, y1, x2, y2, color, w, dash) {
  ctx.save();
  ctx.setLineDash(dash);
  ctx.strokeStyle = color;
  ctx.lineWidth = w;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  ctx.restore();
}

function serif(px) { return px + "px Georgia, 'Times New Roman', serif"; }
function sans(px) { return px + "px system-ui, sans-serif"; }

var figPlugin = {
  id: 'figplug',
  beforeDatasetsDraw: function (c) { drawBack(c); },
  afterDatasetsDraw: function (c) { drawFront(c); }
};

function geom(c) {
  var a = c.chartArea;
  var w = a.right - a.left, h = a.bottom - a.top;
  return { a: a, w: w, h: h, base: Math.min(w, h), X: c.scales.x, Y: c.scales.y, ctx: c.ctx };
}

function drawBack(c) {
  var g = geom(c), ctx = g.ctx, a = g.a;
  if (state.mode === 'regions') {
    var px = g.X.getPixelForValue(cl(zStar(), -5, 5));
    ctx.save();
    ctx.fillStyle = 'rgba(110,150,205,0.16)';
    ctx.fillRect(a.left, a.top, px - a.left, g.h);
    ctx.fillStyle = 'rgba(217,114,76,0.14)';
    ctx.fillRect(px, a.top, a.right - px, g.h);
    ctx.restore();
  }
  // faint dotted guides at sig=0.5 and z=0 (original figure)
  var dw = Math.max(1, g.base * 0.004);
  var dash = [Math.max(1.2, g.base * 0.006), Math.max(2.4, g.base * 0.012)];
  var y5 = g.Y.getPixelForValue(0.5), x0 = g.X.getPixelForValue(0);
  dline(ctx, a.left, y5, x0, y5, GUIDE, dw, dash);
  dline(ctx, x0, a.bottom, x0, y5, GUIDE, dw, dash);
}

function drawFront(c) {
  var g = geom(c), ctx = g.ctx, a = g.a, base = g.base;
  var fsSmall = cl(base * 0.042, 8, 16);
  var fsMed = cl(base * 0.05, 9, 18);

  /* ---- black box frame + minor ticks ---- */
  ctx.save();
  ctx.strokeStyle = '#000';
  ctx.lineWidth = Math.max(1.6, base * 0.0085);
  ctx.strokeRect(a.left, a.top, g.w, g.h);
  var minor = Math.max(3, base * 0.014), major = Math.max(5, base * 0.026);
  ctx.lineWidth = Math.max(1.1, base * 0.005);
  ctx.beginPath();
  for (var z = -5; z <= 5.0001; z += 0.5) {
    var px = g.X.getPixelForValue(z);
    var L = (Math.abs(z) === 5 || z === 0) ? major : minor;
    ctx.moveTo(px, a.bottom); ctx.lineTo(px, a.bottom + L);
  }
  for (var p = 0; p <= 1.0001; p += 0.1) {
    var py = g.Y.getPixelForValue(p);
    var L2 = (p < 0.001 || p > 0.999) ? major : minor;
    ctx.moveTo(a.left, py); ctx.lineTo(a.left - L2, py);
  }
  ctx.stroke();
  ctx.restore();

  /* ---- formula annotation, upper centre ---- */
  var ffs = cl(base * 0.072, 9, 28);
  var cx = a.left + g.w * 0.50;
  var barY = a.top + g.h * 0.145;
  ctx.save();
  ctx.font = serif(ffs);
  var den = '1+exp[\u2212z]';
  var denW = ctx.measureText(den).width;
  ctx.restore();
  haloText(ctx, '1', cx, barY - ffs * 0.20, serif(ffs), '#111', 'center', 'bottom', 4);
  haloText(ctx, den, cx, barY + ffs * 0.20, serif(ffs), '#111', 'center', 'top', 4);
  ctx.save();
  ctx.strokeStyle = '#111';
  ctx.lineWidth = Math.max(1, ffs * 0.055);
  ctx.beginPath();
  ctx.moveTo(cx - denW / 2 - ffs * 0.08, barY);
  ctx.lineTo(cx + denW / 2 + ffs * 0.08, barY);
  ctx.stroke();
  ctx.restore();

  /* ---- threshold + decision boundary ---- */
  var thrY = g.Y.getPixelForValue(state.threshold);
  if (state.showThreshold || state.mode === 'regions') {
    var zs = zStar(), zsc = cl(zs, -5, 5);
    var bx = g.X.getPixelForValue(zsc);
    var dash2 = [Math.max(4, base * 0.018), Math.max(3, base * 0.013)];
    dline(ctx, a.left, thrY, a.right, thrY, THRESH, Math.max(1.2, base * 0.006), dash2);
    dline(ctx, bx, a.bottom, bx, thrY, THRESH, Math.max(1.2, base * 0.006), dash2);
    // crossing dot
    ctx.save();
    ctx.fillStyle = THRESH;
    ctx.beginPath();
    ctx.arc(bx, thrY, Math.max(2.5, base * 0.011), 0, 6.2832);
    ctx.fill();
    ctx.restore();
    // threshold label (left end, above the line if room)
    var tLabY = (thrY - fsSmall * 0.6 < a.top + fsSmall) ? thrY + fsSmall * 0.9 : thrY - fsSmall * 0.5;
    haloText(ctx, 'threshold p = ' + state.threshold.toFixed(2), a.left + g.w * 0.02, tLabY,
      sans(fsSmall), THRESH, 'left', 'bottom', 3.5);
    // z* label near bottom of the dashed drop
    var zTxt = 'z* = ' + (Math.abs(zs) > 5 ? (zs > 0 ? '>5' : '<\u22125') : zs.toFixed(2));
    var rightSide = bx < a.right - g.w * 0.22;
    haloText(ctx, zTxt, bx + (rightSide ? base * 0.02 : -base * 0.02), a.bottom - g.h * 0.03,
      sans(fsSmall), THRESH, rightSide ? 'left' : 'right', 'alphabetic', 3.5);
  }

  /* ---- class region labels ---- */
  if (state.mode === 'regions') {
    var bxr = g.X.getPixelForValue(cl(zStar(), -5, 5));
    var y0lab = a.top + g.h * 0.09;
    if (Math.abs(y0lab - thrY) < g.h * 0.07) y0lab = a.top + g.h * 0.24;
    var y1lab = a.top + g.h * 0.46;
    if (Math.abs(y1lab - thrY) < g.h * 0.07) y1lab = a.top + g.h * 0.64;
    if (bxr - a.left > g.w * 0.16) {
      haloText(ctx, 'predict 0', a.left + g.w * 0.035, y0lab, sans(fsSmall), '#3a5c8a', 'left', 'middle', 3.5);
    }
    if (a.right - bxr > g.w * 0.16) {
      haloText(ctx, 'predict 1', a.right - g.w * 0.035, y1lab, sans(fsSmall), '#a8512c', 'right', 'middle', 3.5);
    }
  }

  /* ---- legend for slope overlay ---- */
  if (state.mode === 'slope') {
    var items = [['sig[z]', ORANGE], ['sig[z](1\u2212sig[z])', PURPLE]];
    ctx.save();
    ctx.font = sans(fsSmall);
    var tw = 0;
    for (var k = 0; k < items.length; k++) tw = Math.max(tw, ctx.measureText(items[k][0]).width);
    ctx.restore();
    var sampleW = base * 0.075, pad = base * 0.022;
    var boxW = sampleW + pad * 2.4 + tw, boxH = pad * 2 + items.length * fsSmall * 1.6;
    var bx0 = a.right - g.w * 0.04 - boxW, by0 = a.top + g.h * 0.40;
    ctx.save();
    ctx.fillStyle = 'rgba(255,255,255,0.88)';
    ctx.strokeStyle = '#d7d7d7';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.rect(bx0, by0, boxW, boxH);
    ctx.fill(); ctx.stroke();
    for (var m = 0; m < items.length; m++) {
      var yy = by0 + pad + fsSmall * 0.8 + m * fsSmall * 1.6;
      ctx.strokeStyle = items[m][1];
      ctx.lineWidth = m === 0 ? Math.max(2, base * 0.012) : Math.max(1.2, base * 0.006);
      ctx.beginPath(); ctx.moveTo(bx0 + pad, yy); ctx.lineTo(bx0 + pad + sampleW, yy); ctx.stroke();
      haloText(ctx, items[m][0], bx0 + pad * 1.4 + sampleW, yy, sans(fsSmall), '#333', 'left', 'middle', 0);
    }
    ctx.restore();
  }

  /* ---- draggable marker ---- */
  var mz = markerZ();
  if (mz !== null && mz !== undefined) {
    var mv = sigf(mz);
    var mx = g.X.getPixelForValue(mz), my = g.Y.getPixelForValue(mv);
    ctx.save();
    ctx.setLineDash([Math.max(1.2, base * 0.006), Math.max(2.4, base * 0.012)]);
    ctx.strokeStyle = '#999';
    ctx.lineWidth = Math.max(1, base * 0.004);
    ctx.beginPath();
    ctx.moveTo(mx, a.bottom); ctx.lineTo(mx, my);
    ctx.moveTo(a.left, my); ctx.lineTo(mx, my);
    ctx.stroke();
    ctx.restore();
    ctx.save();
    ctx.fillStyle = '#2b2b2b';
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = Math.max(1, base * 0.005);
    ctx.beginPath();
    ctx.arc(mx, my, Math.max(3, base * 0.016), 0, 6.2832);
    ctx.fill(); ctx.stroke();
    ctx.restore();
    // readout box
    var txt = 'z = ' + mz.toFixed(2) + '   sig = ' + mv.toFixed(2);
    ctx.save(); ctx.font = sans(fsSmall); var twd = ctx.measureText(txt).width; ctx.restore();
    var padR = base * 0.018;
    var bw = twd + padR * 2, bh = fsSmall * 1.75;
    var rx = mx + base * 0.03, ry = my - bh - base * 0.03;
    if (rx + bw > a.right - 4) rx = mx - bw - base * 0.03;
    if (ry < a.top + 4) ry = my + base * 0.03;
    ctx.save();
    ctx.fillStyle = 'rgba(255,255,255,0.92)';
    ctx.strokeStyle = '#9a9a9a';
    ctx.lineWidth = 1;
    ctx.beginPath(); ctx.rect(rx, ry, bw, bh); ctx.fill(); ctx.stroke();
    ctx.restore();
    haloText(ctx, txt, rx + padR, ry + bh / 2, sans(fsSmall), '#222', 'left', 'middle', 0);
  }
}

/* ---------- chart ---------- */
var canvas = document.createElement('canvas');
canvas.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(canvas);

function applyScale(c) {
  var base = Math.min(c.width, c.height);
  var tickFS = cl(base * 0.05, 8, 20);
  var titleFS = cl(base * 0.062, 9, 24);
  c.options.scales.x.ticks.font = { family: "Georgia, 'Times New Roman', serif", size: tickFS };
  c.options.scales.y.ticks.font = { family: "Georgia, 'Times New Roman', serif", size: tickFS };
  c.options.scales.x.ticks.padding = Math.max(6, base * 0.032);
  c.options.scales.y.ticks.padding = Math.max(6, base * 0.032);
  c.options.scales.x.title.font = { family: "Georgia, 'Times New Roman', serif", size: titleFS, style: 'italic' };
  c.options.scales.y.title.font = { family: "Georgia, 'Times New Roman', serif", size: titleFS };
  c.data.datasets[0].borderWidth = Math.max(2, base * 0.014);
  c.data.datasets[1].borderWidth = Math.max(1.2, base * 0.007);
}

chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
  data: {
    datasets: [
      { label: 'sig[z]', data: sigData, parsing: false, borderColor: ORANGE, borderWidth: 6, pointRadius: 0, fill: false, tension: 0, borderCapStyle: 'round', borderJoinStyle: 'round', order: 1 },
      { label: 'slope', data: slopeData, parsing: false, borderColor: PURPLE, borderWidth: 2, pointRadius: 0, fill: false, tension: 0, hidden: true, order: 2 }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    events: [],
    layout: { padding: { top: 6, right: 10, bottom: 2, left: 2 } },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: {
        type: 'linear', min: -5, max: 5,
        grid: { display: false, drawTicks: false },
        border: { display: false },
        afterBuildTicks: function (ax) { ax.ticks = [{ value: -5 }, { value: 0 }, { value: 5 }]; },
        ticks: { color: '#000', callback: function (v) { return Number(v).toFixed(1); } },
        title: { display: true, text: 'z', color: '#000' }
      },
      y: {
        type: 'linear', min: 0, max: 1,
        grid: { display: false, drawTicks: false },
        border: { display: false },
        afterBuildTicks: function (ax) { ax.ticks = [{ value: 0 }, { value: 1 }]; },
        ticks: { color: '#000', callback: function (v) { return Number(v).toFixed(1); } },
        title: { display: true, text: 'sig[z]', color: '#000' }
      }
    },
    onResize: function (c) { applyScale(c); }
  },
  plugins: [figPlugin]
});
applyScale(chart);
chart.update('none');
window.__markRendered();

document.addEventListener('fig-resize', function () { chart.resize(); });

/* ---------- pointer interaction on the curve ---------- */
function pointerZ(ev) {
  var r = canvas.getBoundingClientRect();
  var px = ev.clientX - r.left;
  return cl(chart.scales.x.getValueForPixel(px), -5, 5);
}
function nearCurve(ev) {
  var r = canvas.getBoundingClientRect();
  var px = ev.clientX - r.left, py = ev.clientY - r.top;
  var a = chart.chartArea;
  if (px < a.left - 8 || px > a.right + 8 || py < a.top - 8 || py > a.bottom + 8) return false;
  var z = cl(chart.scales.x.getValueForPixel(px), -5, 5);
  var cy = chart.scales.y.getPixelForValue(sigf(z));
  var tol = Math.max(10, Math.min(a.right - a.left, a.bottom - a.top) * 0.06);
  return Math.abs(py - cy) < tol;
}
function syncPointUI(z) {
  document.getElementById('zpointInput').value = z.toFixed(2);
  document.getElementById('zpointVal').value = z.toFixed(2);
  var s = sigf(z);
  document.getElementById('readout').textContent =
    'sig[' + z.toFixed(2) + '] = ' + s.toFixed(3) + '   •   slope = ' + (s * (1 - s)).toFixed(3);
}

canvas.addEventListener('pointerdown', function (e) {
  if (nearCurve(e)) {
    dragging = true; movedWhileDown = false;
    canvas.setPointerCapture(e.pointerId);
    var z = pointerZ(e);
    state.pinZ = z; hoverZ = null; syncPointUI(z); chart.update('none');
  }
});
canvas.addEventListener('pointermove', function (e) {
  if (dragging) {
    movedWhileDown = true;
    var z = pointerZ(e);
    state.pinZ = z; hoverZ = null; syncPointUI(z); chart.update('none');
    showTooltip('z = ' + z.toFixed(2) + '  →  sig[z] = ' + sigf(z).toFixed(3), e);
    return;
  }
  if (nearCurve(e)) {
    canvas.style.cursor = 'pointer';
    var zz = pointerZ(e);
    hoverZ = zz; chart.update('none');
    showTooltip('z = ' + zz.toFixed(2) + '  →  sig[z] = ' + sigf(zz).toFixed(3) +
      '   (slope ' + (sigf(zz) * (1 - sigf(zz))).toFixed(3) + ')', e);
  } else {
    canvas.style.cursor = 'default';
    if (hoverZ !== null) { hoverZ = null; chart.update('none'); }
    hideTooltip();
  }
});
canvas.addEventListener('pointerup', function (e) {
  if (dragging && !movedWhileDown) {
    var z = pointerZ(e), s = sigf(z);
    showPopup('Reading the sigmoid at z = ' + z.toFixed(2),
      'The score z = ' + z.toFixed(2) + ' is squashed to the probability sig[z] = ' + s.toFixed(3) +
      '. The local slope there is sig[z](1−sig[z]) = ' + (s * (1 - s)).toFixed(3) +
      ', at most 0.25 (at z = 0) and nearly zero in the tails. That is why the output changes quickly near the middle and barely moves once the score saturates.');
  }
  dragging = false;
});
canvas.addEventListener('pointerleave', function () {
  hoverZ = null; hideTooltip(); chart.update('none');
});

/* ---------- controls ---------- */
function update_threshold(v) {
  state.threshold = v;
  state.showThreshold = true;
  chart.update('none');
}
function update_viewMode(mode) {
  state.mode = mode;
  chart.setDatasetVisibility(1, mode === 'slope');
  chart.update('none');
}
function update_zpoint(v) {
  state.pinZ = v; hoverZ = null;
  syncPointUI(v);
  chart.update('none');
}
function trigger_clearPoint() {
  state.pinZ = null; hoverZ = null;
  document.getElementById('zpointVal').value = '—';
  document.getElementById('readout').textContent = '';
  chart.update('none');
}

