Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<span style="font-weight:600;font-size:12.5px">Logistic sigmoid: scores → probabilities</span>
<span id="demoNarration" style="display:block;font-size:11.5px;line-height:1.45;color:#222;background:#fff;border:1px solid #e2e5e9;border-radius:4px;padding:6px 7px;min-height:62px"></span>
<span style="display:flex;gap:6px;align-items:center">
  <button onclick="prevStep()">◀</button>
  <span id="stepLabel" style="font-size:11px;color:#444"></span>
  <button onclick="nextStep()">▶</button>
</span>
<label>Probability threshold: <output id="thresholdVal">0.50</output>
  <input id="thresholdInput" type="range" min="0.05" max="0.95" step="0.01" value="0.5"
    oninput="document.getElementById('thresholdVal').value=(+this.value).toFixed(2);update_threshold(+this.value)">
</label>
<label>Overlay
  <select id="viewModeInput" onchange="update_viewMode(this.value)" style="font-size:12px;padding:2px">
    <option value="sigmoid">Sigmoid only</option>
    <option value="slope">Sigmoid + slope</option>
    <option value="regions">Decision regions</option>
  </select>
</label>
<label>Point on curve, z = <output id="zpointVal">—</output>
  <input id="zpointInput" type="range" min="-5" max="5" step="0.05" value="0"
    oninput="document.getElementById('zpointVal').value=(+this.value).toFixed(2);update_zpoint(+this.value)">
</label>
<button onclick="trigger_clearPoint()">Clear point</button>
<span id="readout" style="font-size:11px;color:#444;line-height:1.4"></span>
<span style="font-size:10.5px;color:#666;line-height:1.35">Tip: hover or drag directly on the orange curve; click it for an explanation.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
var ORANGE = '#D9724C';
var PURPLE = '#8B6BB1';
var THRESH = '#3a6ea8';
var GUIDE = '#c9c9c9';

function sigf(z) { return 1 / (1 + Math.exp(-z)); }
function cl(v, a, b) { return v < a ? a : (v > b ? b : v); }

var sigData = [], slopeData = [];
for (var i = 0; i <= 320; i++) {
  var z = -5 + 10 * i / 320;
  var s = sigf(z);
  sigData.push({ x: z, y: s });
  slopeData.push({ x: z, y: s * (1 - s) });
}

var state = { threshold: 0.5, mode: 'sigmoid', pinZ: null, showThreshold: false };
var hoverZ = null, dragging = false, movedWhileDown = false;
var chart = null;

function zStar() { var t = state.threshold; return Math.log(t / (1 - t)); }
function markerZ() { return hoverZ !== null ? hoverZ : state.pinZ; }

/* ---------- drawing helpers ---------- */
function haloText(ctx, txt, x, y, font, color, align, baseline, halo) {
  ctx.save();
  ctx.font = font;
  ctx.textAlign = align || 'left';
  ctx.textBaseline = baseline || 'alphabetic';
  if (halo !== 0) {
    ctx.lineWidth = halo || 3;
    ctx.strokeStyle = '#fff';
    ctx.lineJoin = 'round';
    ctx.strokeText(txt, x, y);
  }
  ctx.fillStyle = color;
  ctx.fillText(txt, x, y);
  ctx.restore();
}

/* boxed label: white plate behind text, always vertically centred on y */
function boxedText(ctx, txt, x, y, fs, font, color, align) {
  ctx.save();
  ctx.font = font;
  var tw = ctx.measureText(txt).width;
  var pad = fs * 0.38;
  var bw = tw + pad * 2, bh = fs * 1.55;
  var bx = align === 'right' ? (x - bw) : (align === 'center' ? (x - bw / 2) : x);
  var by = y - bh / 2;
  ctx.fillStyle = 'rgba(255,255,255,0.92)';
  ctx.strokeStyle = 'rgba(0,0,0,0.10)';
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.rect(bx, by, bw, bh);
  ctx.fill();
  ctx.stroke();
  ctx.fillStyle = color;
  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.fillText(txt, bx + pad, y);
  ctx.restore();
  return { x: bx, y: by, w: bw, h: bh };
}

function dline(ctx, x1, y1, x2, y2, color, w, dash) {
  ctx.save();
  ctx.setLineDash(dash);
  ctx.strokeStyle = color;
  ctx.lineWidth = w;
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x2, y2);
  ctx.stroke();
  ctx.restore();
}

function serif(px) { return px + "px Georgia, 'Times New Roman', serif"; }
function sans(px) { return px + "px system-ui, sans-serif"; }

var figPlugin = {
  id: 'figplug',
  beforeDatasetsDraw: function (c) { drawBack(c); },
  afterDatasetsDraw: function (c) { drawFront(c); }
};

function geom(c) {
  var a = c.chartArea;
  var w = a.right - a.left, h = a.bottom - a.top;
  return { a: a, w: w, h: h, base: Math.min(w, h), X: c.scales.x, Y: c.scales.y, ctx: c.ctx };
}

function drawBack(c) {
  var g = geom(c), ctx = g.ctx, a = g.a;
  if (state.mode === 'regions') {
    var px = g.X.getPixelForValue(cl(zStar(), -5, 5));
    ctx.save();
    ctx.fillStyle = 'rgba(110,150,205,0.16)';
    ctx.fillRect(a.left, a.top, px - a.left, g.h);
    ctx.fillStyle = 'rgba(217,114,76,0.14)';
    ctx.fillRect(px, a.top, a.right - px, g.h);
    ctx.restore();
  }
  // faint dotted guides at sig=0.5 and z=0 (as in the source figure)
  var dw = Math.max(1, g.base * 0.004);
  var dash = [Math.max(1.2, g.base * 0.006), Math.max(2.4, g.base * 0.012)];
  var y5 = g.Y.getPixelForValue(0.5), x0 = g.X.getPixelForValue(0);
  dline(ctx, a.left, y5, x0, y5, GUIDE, dw, dash);
  dline(ctx, x0, a.bottom, x0, y5, GUIDE, dw, dash);
}

function drawFront(c) {
  var g = geom(c), ctx = g.ctx, a = g.a, base = g.base;
  var fsSmall = cl(base * 0.044, 8, 17);

  /* ---- black box frame + minor ticks ---- */
  ctx.save();
  ctx.strokeStyle = '#000';
  ctx.lineWidth = Math.max(1.8, base * 0.009);
  ctx.strokeRect(a.left, a.top, g.w, g.h);
  var minor = Math.max(3, base * 0.014), major = Math.max(5, base * 0.026);
  ctx.lineWidth = Math.max(1.1, base * 0.005);
  ctx.beginPath();
  for (var z = -5; z <= 5.0001; z += 0.5) {
    var px = g.X.getPixelForValue(z);
    var L = (Math.abs(z) === 5 || z === 0) ? major : minor;
    ctx.moveTo(px, a.bottom); ctx.lineTo(px, a.bottom + L);
  }
  for (var p = 0; p <= 1.0001; p += 0.1) {
    var py = g.Y.getPixelForValue(p);
    var L2 = (p < 0.001 || p > 0.999) ? major : minor;
    ctx.moveTo(a.left, py); ctx.lineTo(a.left - L2, py);
  }
  ctx.stroke();
  ctx.restore();

  /* ---- formula annotation: upper-LEFT-of-centre, clear of the curve ---- */
  var ffs = cl(base * 0.078, 9, 30);
  var den = '1+exp[\u2212z]';
  ctx.save();
  ctx.font = serif(ffs);
  var denW = ctx.measureText(den).width;
  ctx.restore();
  var maxW = g.w * 0.40;
  if (denW > maxW) {
    ffs = ffs * maxW / denW;
    ctx.save(); ctx.font = serif(ffs); denW = ctx.measureText(den).width; ctx.restore();
  }
  var cx = a.left + g.w * 0.34;
  var barY = a.top + g.h * 0.135;
  haloText(ctx, '1', cx, barY - ffs * 0.20, serif(ffs), '#111', 'center', 'bottom', 4);
  haloText(ctx, den, cx, barY + ffs * 0.20, serif(ffs), '#111', 'center', 'top', 4);
  ctx.save();
  ctx.strokeStyle = '#111';
  ctx.lineWidth = Math.max(1, ffs * 0.055);
  ctx.beginPath();
  ctx.moveTo(cx - denW / 2 - ffs * 0.08, barY);
  ctx.lineTo(cx + denW / 2 + ffs * 0.08, barY);
  ctx.stroke();
  ctx.restore();

  /* ---- threshold + decision boundary ---- */
  var thrY = g.Y.getPixelForValue(state.threshold);
  if (state.showThreshold || state.mode === 'regions') {
    var zs = zStar(), zsc = cl(zs, -5, 5);
    var bx = g.X.getPixelForValue(zsc);
    var dash2 = [Math.max(4, base * 0.018), Math.max(3, base * 0.013)];
    dline(ctx, a.left, thrY, a.right, thrY, THRESH, Math.max(1.3, base * 0.0065), dash2);
    dline(ctx, bx, a.bottom, bx, thrY, THRESH, Math.max(1.3, base * 0.0065), dash2);
    ctx.save();
    ctx.fillStyle = THRESH;
    ctx.beginPath();
    ctx.arc(bx, thrY, Math.max(2.5, base * 0.011), 0, 6.2832);
    ctx.fill();
    ctx.restore();

    // threshold label: left+above when the line is low enough; otherwise right+below
    var tTxt = 'threshold p = ' + state.threshold.toFixed(2);
    if (thrY > a.top + g.h * 0.33) {
      boxedText(ctx, tTxt, a.left + g.w * 0.025, thrY - fsSmall * 1.25, fsSmall, sans(fsSmall), THRESH, 'left');
    } else {
      boxedText(ctx, tTxt, a.right - g.w * 0.025, thrY + fsSmall * 1.35, fsSmall, sans(fsSmall), THRESH, 'right');
    }

    // z* label at the foot of the dashed drop, on a white plate
    var zTxt = 'z* = ' + (Math.abs(zs) > 5 ? (zs > 0 ? '>5' : '<\u22125') : zs.toFixed(2));
    var rightSide = bx < a.right - g.w * 0.26;
    boxedText(ctx, zTxt,
      bx + (rightSide ? base * 0.022 : -base * 0.022),
      a.bottom - g.h * 0.055, fsSmall, sans(fsSmall), THRESH, rightSide ? 'left' : 'right');
  }

  /* ---- class region labels (placed in curve-free corners) ---- */
  if (state.mode === 'regions') {
    var bxr = g.X.getPixelForValue(cl(zStar(), -5, 5));
    var y0lab = a.top + g.h * 0.45;
    if (Math.abs(y0lab - thrY) < g.h * 0.08) y0lab = a.top + g.h * 0.60;
    var y1lab = a.top + g.h * 0.58;
    if (Math.abs(y1lab - thrY) < g.h * 0.08) y1lab = a.top + g.h * 0.42;
    if (bxr - a.left > g.w * 0.26) {
      boxedText(ctx, 'predict 0', a.left + g.w * 0.03, y0lab, fsSmall, sans(fsSmall), '#3a5c8a', 'left');
    }
    if (a.right - bxr > g.w * 0.26) {
      boxedText(ctx, 'predict 1', a.right - g.w * 0.03, y1lab, fsSmall, sans(fsSmall), '#a8512c', 'right');
    }
  }

  /* ---- legend for slope overlay ---- */
  if (state.mode === 'slope') {
    var items = [['sig[z]', ORANGE], ['sig[z](1\u2212sig[z])', PURPLE]];
    ctx.save();
    ctx.font = sans(fsSmall);
    var tw = 0;
    for (var k = 0; k < items.length; k++) tw = Math.max(tw, ctx.measureText(items[k][0]).width);
    ctx.restore();
    var sampleW = base * 0.075, pad = base * 0.022;
    var boxW = sampleW + pad * 2.4 + tw, boxH = pad * 2 + items.length * fsSmall * 1.6;
    var bx0 = a.right - g.w * 0.04 - boxW, by0 = a.top + g.h * 0.42;
    ctx.save();
    ctx.fillStyle = 'rgba(255,255,255,0.90)';
    ctx.strokeStyle = '#d7d7d7';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.rect(bx0, by0, boxW, boxH);
    ctx.fill(); ctx.stroke();
    for (var m = 0; m < items.length; m++) {
      var yy = by0 + pad + fsSmall * 0.8 + m * fsSmall * 1.6;
      ctx.strokeStyle = items[m][1];
      ctx.lineWidth = m === 0 ? Math.max(2.4, base * 0.014) : Math.max(1.2, base * 0.006);
      ctx.beginPath(); ctx.moveTo(bx0 + pad, yy); ctx.lineTo(bx0 + pad + sampleW, yy); ctx.stroke();
      haloText(ctx, items[m][0], bx0 + pad * 1.4 + sampleW, yy, sans(fsSmall), '#333', 'left', 'middle', 0);
    }
    ctx.restore();
  }

  /* ---- draggable marker ---- */
  var mz = markerZ();
  if (mz !== null && mz !== undefined) {
    var mv = sigf(mz);
    var mx = g.X.getPixelForValue(mz), my = g.Y.getPixelForValue(mv);
    ctx.save();
    ctx.setLineDash([Math.max(1.2, base * 0.006), Math.max(2.4, base * 0.012)]);
    ctx.strokeStyle = '#999';
    ctx.lineWidth = Math.max(1, base * 0.004);
    ctx.beginPath();
    ctx.moveTo(mx, a.bottom); ctx.lineTo(mx, my);
    ctx.moveTo(a.left, my); ctx.lineTo(mx, my);
    ctx.stroke();
    ctx.restore();
    ctx.save();
    ctx.fillStyle = '#2b2b2b';
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = Math.max(1, base * 0.005);
    ctx.beginPath();
    ctx.arc(mx, my, Math.max(3, base * 0.016), 0, 6.2832);
    ctx.fill(); ctx.stroke();
    ctx.restore();
    var txt = 'z = ' + mz.toFixed(2) + '   sig = ' + mv.toFixed(2);
    ctx.save(); ctx.font = sans(fsSmall); var twd = ctx.measureText(txt).width; ctx.restore();
    var padR = fsSmall * 0.38;
    var bw = twd + padR * 2, bh = fsSmall * 1.55;
    var rx = mx + base * 0.03, ry = my - bh - base * 0.03;
    if (rx + bw > a.right - 4) rx = mx - bw - base * 0.03;
    if (rx < a.left + 4) rx = a.left + 4;
    if (ry < a.top + 4) ry = my + base * 0.03;
    boxedText(ctx, txt, rx, ry + bh / 2, fsSmall, sans(fsSmall), '#222', 'left');
  }
}

/* ---------- chart ---------- */
var canvas = document.createElement('canvas');
canvas.style.cssText = 'width:100%;height:100%;display:block';
document.getElementById('container').appendChild(canvas);

function applyScale(c) {
  var base = Math.min(c.width, c.height);
  var tickFS = cl(base * 0.060, 11, 26);
  var titleFS = cl(base * 0.072, 12, 30);
  c.options.scales.x.ticks.font = { family: "Georgia, 'Times New Roman', serif", size: tickFS };
  c.options.scales.y.ticks.font = { family: "Georgia, 'Times New Roman', serif", size: tickFS };
  c.options.scales.x.ticks.padding = Math.max(4, base * 0.016);
  c.options.scales.y.ticks.padding = Math.max(4, base * 0.016);
  c.options.scales.x.title.font = { family: "Georgia, 'Times New Roman', serif", size: titleFS, style: 'italic' };
  c.options.scales.y.title.font = { family: "Georgia, 'Times New Roman', serif", size: titleFS };
  c.options.scales.x.title.padding = { top: Math.max(2, base * 0.012) };
  c.options.scales.y.title.padding = { bottom: Math.max(2, base * 0.010) };
  c.data.datasets[0].borderWidth = Math.max(3, base * 0.019);
  c.data.datasets[1].borderWidth = Math.max(1.4, base * 0.008);
}

chart = new Chart(canvas.getContext('2d'), {
  type: 'line',
  data: {
    datasets: [
      { label: 'sig[z]', data: sigData, parsing: false, borderColor: ORANGE, borderWidth: 7, pointRadius: 0, fill: false, tension: 0, borderCapStyle: 'round', borderJoinStyle: 'round', order: 1 },
      { label: 'slope', data: slopeData, parsing: false, borderColor: PURPLE, borderWidth: 2, pointRadius: 0, fill: false, tension: 0, hidden: true, order: 2 }
    ]
  },
  options: {
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    events: [],
    layout: { padding: { top: 8, right: 12, bottom: 2, left: 2 } },
    plugins: { legend: { display: false }, tooltip: { enabled: false } },
    scales: {
      x: {
        type: 'linear', min: -5, max: 5,
        grid: { display: false, drawTicks: false },
        border: { display: false },
        afterBuildTicks: function (ax) { ax.ticks = [{ value: -5 }, { value: 0 }, { value: 5 }]; },
        ticks: { color: '#000', callback: function (v) { return Number(v).toFixed(1); } },
        title: { display: true, text: 'z', color: '#000' }
      },
      y: {
        type: 'linear', min: 0, max: 1,
        grid: { display: false, drawTicks: false },
        border: { display: false },
        afterBuildTicks: function (ax) { ax.ticks = [{ value: 0 }, { value: 1 }]; },
        ticks: { color: '#000', callback: function (v) { return Number(v).toFixed(1); } },
        title: { display: true, text: 'sig[z]', color: '#000' }
      }
    },
    onResize: function (c) { applyScale(c); }
  },
  plugins: [figPlugin]
});
applyScale(chart);
chart.update('none');
window.__markRendered();

document.addEventListener('fig-resize', function () { chart.resize(); });

/* ---------- pointer interaction on the curve ---------- */
function pointerZ(ev) {
  var r = canvas.getBoundingClientRect();
  var px = ev.clientX - r.left;
  return cl(chart.scales.x.getValueForPixel(px), -5, 5);
}
function nearCurve(ev) {
  var r = canvas.getBoundingClientRect();
  var px = ev.clientX - r.left, py = ev.clientY - r.top;
  var a = chart.chartArea;
  if (px < a.left - 8 || px > a.right + 8 || py < a.top - 8 || py > a.bottom + 8) return false;
  var z = cl(chart.scales.x.getValueForPixel(px), -5, 5);
  var cy = chart.scales.y.getPixelForValue(sigf(z));
  var tol = Math.max(10, Math.min(a.right - a.left, a.bottom - a.top) * 0.06);
  return Math.abs(py - cy) < tol;
}
function syncPointUI(z) {
  document.getElementById('zpointInput').value = z.toFixed(2);
  document.getElementById('zpointVal').value = z.toFixed(2);
  var s = sigf(z);
  document.getElementById('readout').textContent =
    'sig[' + z.toFixed(2) + '] = ' + s.toFixed(3) + '   •   slope = ' + (s * (1 - s)).toFixed(3);
}

canvas.addEventListener('pointerdown', function (e) {
  if (nearCurve(e)) {
    dragging = true; movedWhileDown = false;
    canvas.setPointerCapture(e.pointerId);
    var z = pointerZ(e);
    state.pinZ = z; hoverZ = null; syncPointUI(z); chart.update('none');
  }
});
canvas.addEventListener('pointermove', function (e) {
  if (dragging) {
    movedWhileDown = true;
    var z = pointerZ(e);
    state.pinZ = z; hoverZ = null; syncPointUI(z); chart.update('none');
    showTooltip('z = ' + z.toFixed(2) + '  →  sig[z] = ' + sigf(z).toFixed(3), e);
    return;
  }
  if (nearCurve(e)) {
    canvas.style.cursor = 'pointer';
    var zz = pointerZ(e);
    hoverZ = zz; chart.update('none');
    showTooltip('z = ' + zz.toFixed(2) + '  →  sig[z] = ' + sigf(zz).toFixed(3) +
      '   (slope ' + (sigf(zz) * (1 - sigf(zz))).toFixed(3) + ')', e);
  } else {
    canvas.style.cursor = 'default';
    if (hoverZ !== null) { hoverZ = null; chart.update('none'); }
    hideTooltip();
  }
});
canvas.addEventListener('pointerup', function (e) {
  if (dragging && !movedWhileDown) {
    var z = pointerZ(e), s = sigf(z);
    showPopup('Reading the sigmoid at z = ' + z.toFixed(2),
      'The score z = ' + z.toFixed(2) + ' is squashed to the probability sig[z] = ' + s.toFixed(3) +
      '. The local slope there is sig[z](1−sig[z]) = ' + (s * (1 - s)).toFixed(3) +
      ', at most 0.25 (at z = 0) and nearly zero in the tails. That is why the output changes quickly near the middle and barely moves once the score saturates.');
  }
  dragging = false;
});
canvas.addEventListener('pointerleave', function () {
  hoverZ = null; hideTooltip(); chart.update('none');
});

/* ---------- controls ---------- */
function update_threshold(v) {
  state.threshold = v;
  state.showThreshold = true;
  chart.update('none');
}
function update_viewMode(mode) {
  state.mode = mode;
  chart.setDatasetVisibility(1, mode === 'slope');
  chart.update('none');
}
function update_zpoint(v) {
  state.pinZ = v; hoverZ = null;
  syncPointUI(v);
  chart.update('none');
}
function trigger_clearPoint() {
  state.pinZ = null; hoverZ = null;
  document.getElementById('zpointVal').value = '—';
  document.getElementById('readout').textContent = '';
  chart.update('none');
}

/* ---------- demo steps ---------- */
var DEMO = [
  {
    title: 'The S-curve',
    narration: 'The orange curve maps every real number z onto a value between 0 and 1. Drag the point along the curve: no matter how far out you go, the output never quite reaches 0 or 1.',
    state: { viewMode: 'sigmoid', threshold: 0.5, point: null, showThreshold: false }
  },
  {
    title: 'The midpoint at z = 0',
    narration: 'The dotted guides meet where sig[0] = 0.5 exactly. This is the curve\u2019s centre of symmetry and its steepest point — a zero score means complete uncertainty between the two classes.',
    state: { viewMode: 'sigmoid', threshold: 0.5, point: 0, showThreshold: false }
  },
  {
    title: 'Slope and saturation',
    narration: 'Overlay the slope: it is largest at z = 0 and collapses toward zero in both tails. Drag the point out to z = ±4 and watch how little the output moves — this flatness is the vanishing-gradient problem.',
    state: { viewMode: 'slope', threshold: 0.5, point: 3.5, showThreshold: false }
  },
  {
    title: 'Choosing a threshold',
    narration: 'Set the probability threshold to 0.50 and the decision boundary sits at z = 0. The horizontal line crosses the curve at exactly one place, because the sigmoid is strictly increasing.',
    state: { viewMode: 'regions', threshold: 0.5, point: null, showThreshold: true }
  },
  {
    title: 'A conservative threshold',
    narration: 'Raise the threshold to 0.90 and the boundary jumps out to z ≈ 2.2 — demanding high confidence costs a large margin in z. Push it toward 0.95 and the boundary runs off toward the edge of the plot.',
    state: { viewMode: 'regions', threshold: 0.9, point: null, showThreshold: true }
  }
];
var stepIdx = 0;

function applyStep(i) {
  stepIdx = (i + DEMO.length) % DEMO.length;
  var st = DEMO[stepIdx].state;
  document.getElementById('viewModeInput').value = st.viewMode;
  update_viewMode(st.viewMode);
  document.getElementById('thresholdInput').value = st.threshold;
  document.getElementById('thresholdVal').value = st.threshold.toFixed(2);
  state.threshold = st.threshold;
  state.showThreshold = !!st.showThreshold;
  if (st.point === null || st.point === undefined) {
    trigger_clearPoint();
  } else {
    update_zpoint(st.point);
  }
  document.getElementById('demoNarration').textContent =
    DEMO[stepIdx].title + ' — ' + DEMO[stepIdx].narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + DEMO.length;
  chart.update('none');
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
